"use client";
import {ArtemisScope} from "./artemis-scope";
import View0 from "./components/not-found-pages/variants/01-falling-blocks";
import View1 from "./components/not-found-pages/variants/02-flip-panels";
import View2 from "./components/not-found-pages/variants/03-elastic";
import View3 from "./components/not-found-pages/variants/04-echo";
import View4 from "./components/not-found-pages/variants/05-spotlight";
import View5 from "./components/not-found-pages/variants/06-sliced";
import View6 from "./components/not-found-pages/variants/07-editorial";
import View7 from "./components/not-found-pages/variants/08-terminal";
import View8 from "./components/not-found-pages/variants/09-wayfinder";
const views={"falling-blocks":View0,"flip-panels":View1,"elastic":View2,"echo":View3,"spotlight":View4,"sliced":View5,"editorial":View6,"terminal":View7,"wayfinder":View8};
export interface ArtemisNotFoundPagesProps{className?:string;variant?:"falling-blocks"|"flip-panels"|"elastic"|"echo"|"spotlight"|"sliced"|"editorial"|"terminal"|"wayfinder";}
export function ArtemisNotFoundPages({className,variant="falling-blocks"}:ArtemisNotFoundPagesProps){const View=views[variant];return <ArtemisScope className={["art:min-h-dvh art:[&>section]:min-h-dvh",className].filter(Boolean).join(" ")}><View/></ArtemisScope>;}
